using Nancy;using Nancy.ModelBinding;using WMS_HU_Model.Models.Common;using WMS_HU_Model.Models.WeekCode;using WMS_HU_Model.Repositories;using WMS_HU_Model.Services;
namespace WMS.Modules{public class WeekCodeRecalculateModule:NancyModule{public WeekCodeRecalculateModule():base("/api/wms/weekcode"){var mes=new MesFinishedGoodsInboundRepository();var service=new WeekCodeRecalculateService(new WeekCodeRecalculateRepository(),new MesWeekCodeRuleProvider(new MesWeekCodeRuleRepository()),new WeekCodeResolver(new UnavailableWeekCodeRuleProvider()),mes);Post("/recalculate",_=>{var q=this.Bind<WeekCodeRecalculateRequest>();var r=service.Recalculate(q);return r.IsSuccess?Response.AsJson(ApiResult.Success(r.Data)):Response.AsJson(ApiResult.Fail(r.Message),HttpStatusCode.BadRequest);});}}}
